  crew(race, frame, flip) {
    const key = 'crew|' + race + '|' + frame + '|' + (flip ? 1 : 0);
    return this.cached(key, () => {
      const d = this.crewBody(race);
      const grid = d.body.concat(frame ? d.legsB : d.legsA);
      let cv = this.px(grid, d.map);
      if (flip) {
        const f = document.createElement('canvas');
        f.width = cv.width; f.height = cv.height;
        const c = f.getContext('2d');
        c.translate(cv.width, 0); c.scale(-1, 1);
        c.drawImage(cv, 0, 0);
        cv = f;
      }
      return cv;
    });
  },

  // crew portrait (head only, 10x10, boxed)
  portrait(race) {
    return this.cached('port|' + race, () => {
      const d = this.crewBody(race);
      const grid = d.body.slice(0, 6).map(r => r.slice(1, 11));
      const cv = document.createElement('canvas');
      cv.width = 12; cv.height = 12;
      const c = cv.getContext('2d');
      c.fillStyle = COL.dkblue; c.fillRect(0, 0, 12, 12);
      c.drawImage(this.px(grid, d.map), 1, 2);
      return cv;
    });
  },

