  // ============ WEAPON DECK SPRITES (16x8, facing right) ============
  // per-weapon distinctive sprites: every gun has a memorable silhouette tied to
  // what it does (slim iron, fat bands, bells, prongs, pots, crystals, horns...)
  weaponArt(key) {
    const e = this.artEntry('weapon_' + key);
    if (e) return e.img; // imported AI sprite (96x48 file)
    const def = SPR.WPN_PX[key];
    if (!def) return null;
    return this.cached('wart|' + key, () => this.px(def.g, def.m, 1));
  },
  // UI-chip version: baked, area-averaged 32x16 - crisp at chip size where the
  // full-res art garbles under NEAREST downscaling
  weaponIcon(key) {
    // prefer the FULL-res weapon art (downsamples crisp at any display size);
    // the small _icon (sized for the classic 2x view) upscales/blurs on big HD windows
    const full = this.weaponArt(key);
    if (full) return full;
    const e = this.artEntry('weapon_' + key + '_icon');
    return e ? e.img : null;
  },

